"""Create gallery, honest comparison sheets, screenshot boards and ZIP from current exports."""
from pathlib import Path
import json,zipfile,hashlib,shutil,html
from PIL import Image,ImageDraw,ImageFont
P=Path(__file__).resolve().parent.parent
scenes=json.loads((P/'scenes.json').read_text())
devices={'desktop':(1440,1000),'tablet':(834,1112),'mobile':(390,844)}
def gallery():
    nav=''.join(f'<button data-scene="{s["id"]}">{s["id"][:2]} &nbsp; {s["title"]}</button>' for s in scenes)
    cards=''.join(f'<article><h2>{s["id"][:2]} · {s["title"]}</h2><p>{s["description"]}</p><div class="links"><a href="{s["source"]}">Responsive source</a>'+''.join(f'<a href="images/{s["id"]}-{d}.png">{d.title()} PNG</a>' for d in devices)+f'<a href="boards/{s["id"]}.png">Three-device board</a></div></article>' for s in scenes)
    css='''*{box-sizing:border-box}body{margin:0;background:#f7f3eb;color:#302c25;font:17px/1.5 Arial,sans-serif}a{color:#4e573e;text-underline-offset:4px}header{padding:36px 45px;border-bottom:1px solid #c7bcaa}h1{font:42px Georgia,serif;margin:10px 0 16px}h2{font:26px Georgia,serif}p{max-width:860px;color:#625c50}header small{text-transform:uppercase;letter-spacing:.15em}.links{display:flex;flex-wrap:wrap;gap:15px;margin:20px 0}.shell{display:grid;grid-template-columns:280px minmax(0,1fr)}nav{padding:20px;position:sticky;top:0;align-self:start;max-height:100vh;overflow:auto}button{font:inherit;cursor:pointer;background:none;border:1px solid #a99d89;padding:11px;color:#302c25;text-align:left;border-radius:4px}nav button{display:block;width:100%;margin:8px 0}button[aria-pressed=true]{background:#4e573e;color:white}.viewer{padding:30px;min-width:0}.viewer>img{width:100%;height:auto;display:block;border:1px solid #b8ae9c}.modes{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.details{padding:10px 45px 50px}article{padding:25px 0;border-top:1px solid #d4ccbc}a:focus-visible,button:focus-visible{outline:3px solid #005fcc;outline-offset:4px}.disclaimer{background:#e9e2d5;padding:16px 20px;font-size:16px}@media(max-width:800px){header{padding:25px}h1{font-size:32px}.shell{grid-template-columns:1fr}nav{position:static;max-height:260px;border-bottom:1px solid #b8ae9c;padding:20px}.viewer{padding:20px}.details{padding:10px 25px}}'''
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Habitat · 45 responsive mockups</title><style>{css}</style></head><body><header><small>LetBuyy · Craft / Habitat · Design study 1.0</small><h1>Make room for the details.</h1><p>15 connected shopping and account scenes. Each rendered independently at desktop 1440×1000, tablet 834×1112 and mobile 390×844, DPR 1.</p><div class="links"><a href="Habitat-45-mockups.zip">Download 45 PNGs</a><a href="prototype-index.html">Open responsive presentation</a><a href="README.md">Handoff & limitations</a><a href="comparisons/index.html">Shopify comparisons</a><a href="comparisons/neutral-structure.html">Neutral task comparison</a><a href="validation.json">Validation</a></div><p class="disclaimer">Visual targets with fictional catalog, account and quote data. Proposed controls are not working commerce. No production theme has been installed or published by this design pack.</p></header><div class="shell"><nav aria-label="Scenes">{nav}</nav><main class="viewer"><h2 id="scene-title"></h2><p id="scene-description"></p><div class="modes"><button data-mode="board">Three devices</button><button data-mode="desktop">Desktop</button><button data-mode="tablet">Tablet</button><button data-mode="mobile">Mobile</button></div><p><a id="full" href="boards/01-home-top.png">Open full-size PNG</a> · <a id="source" href="source/01-home-top.html">Open this responsive source</a></p><img id="screen" src="boards/01-home-top.png" alt="Habitat home, all three devices"></main></div><section class="details"><h2>All scenes and source files</h2>{cards}</section><script>const scenes={json.dumps(scenes,ensure_ascii=False)};let selected=scenes[0],mode='board';function show(){{document.getElementById('scene-title').textContent=selected.title;document.getElementById('scene-description').textContent=selected.description;const file=mode==='board'?'boards/'+selected.id+'.png':'images/'+selected.id+'-'+mode+'.png';document.getElementById('screen').src=file;document.getElementById('screen').alt=selected.title+' — '+mode;document.getElementById('full').href=file;document.getElementById('source').href=selected.source;document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scene===selected.id)));document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));}}document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{{selected=scenes.find(s=>s.id===b.dataset.scene);show();}});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{{mode=b.dataset.mode;show();}});show();</script></body></html>'''
    (P/'index.html').write_text(page)
    (P/'prototype-index.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Habitat responsive source</title><style>{css}</style><header><a href="index.html">Back to image storybook</a><h1>Habitat responsive source</h1><p>Visual-only presentation. Native text, offline fonts and original imagery. No live forms, cart, login, payment or order requests. Two home segments form one homepage; three chair segments form one product page.</p></header><main class="details">{cards}</main></html>')

def comparisons():
    css='''*{box-sizing:border-box}body{margin:0;padding:36px;background:#f7f3eb;color:#302c25;font:17px/1.5 Arial}h1,h2{font-family:Georgia;font-weight:400}h1{font-size:38px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:25px 0}.panel{min-width:0;background:#fffdfa;border:1px solid #b8ae9c;padding:22px}.crop{height:570px;overflow:hidden;border:1px solid #d4ccbc;margin-top:18px}.crop img{width:100%;height:auto}a{color:#4e573e}p{max-width:1050px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #c7bcaa;padding:13px}table{width:100%;border-collapse:collapse}small{color:#625c50}.pill{background:#e9e2d5;padding:7px 12px;display:inline-block;margin:10px 0}@media(max-width:750px){body{padding:22px}.pair{grid-template-columns:1fr}h1{font-size:31px}.crop{height:450px}table,tbody,tr,td,th{display:block}}'''
    refs=[{'key':'dwell','title':'Dwell · room-led discovery','url':'https://theme-dwell-demo.myshopify.com/','scene':'01-home-top','observation':'Saved public capture: room-oriented lifestyle opening, quiet serif hierarchy and home-category navigation. The dossier records vertical collection filters.','retained':'Room/category entry, material context and large lifestyle imagery.','difference':'An explicit room index sits beside the panorama. Numeric dimensions and a measurement-guide entry address space and access uncertainty.','contract':'A category/navigation; C typed dimensions and public Liquid facts; A/D actual service policy and quote.'},{'key':'craft','title':'Craft · materials and care','url':'https://theme-craft-demo.myshopify.com/products/ceramic-bundle','scene':'05-product-dimensions','observation':'Saved public product capture: Dinnerware Set gallery and a conventional purchase rail, with material/care and set contents in supporting detail. Successful purchase was not tested.','retained':'Material and care information remains near product evaluation.','difference':'Furniture adds assembled versus package dimensions, seat height and an accessible dimension schematic. Finish identity selects only variant-specific facts while common measurements stay stable.','contract':'C dimension namespace, unit normalization and variant inheritance; A/C sanitized merchant material/assembly facts.'}]
    parts=[]
    for r in refs:
      source=f'../../../evidence/{r["key"]}-'+('home' if r['key']=='dwell' else 'product')+'-desktop.jpg'
      parts.append(f'''<section><h2>{r['title']}</h2><p class="pill">Reference viewport: 1440×1000 · DPR 1 · Saved research 22 Oct 2026 · Opening excerpts</p><div class="pair"><div class="panel"><h3>Shopify reference · saved observation</h3><a href="{r['url']}">{r['url']}</a><p>{r['observation']}</p><div class="crop"><img src="{source}" alt="Saved {r['key']} public reference screenshot, see source dossier"></div></div><div class="panel"><h3>Habitat · original design 1.0</h3><a href="../source/{r['scene']}.html">Scene {r['scene']} · responsive source</a><p>{r['difference']}</p><div class="crop"><img src="../images/{r['scene']}-desktop.png" alt="Habitat corresponding design, desktop 1440 CSS pixels"></div></div></div><table><tr><th>User problem</th><td>Can I judge this object in my room and understand the facts before I purchase?</td></tr><tr><th>Convention retained</th><td>{r['retained']}</td></tr><tr><th>Original departure</th><td>{r['difference']}</td></tr><tr><th>Required LetBuyy contract</th><td>{r['contract']}</td></tr></table></section>''')
    (P/'comparisons/index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Habitat · attributable reference comparisons</title><style>{css}</style></head><body><a href="../index.html">Back to storybook</a><h1>Furniture adds a spatial question.</h1><p>These saved Shopify captures are research evidence, separated from original Habitat theme assets. Both panels originate at 1440 CSS px and are shown at equal display widths with opening crops; full-page image heights differ. They are neither cloned page layouts nor evidence of better conversion.</p>{''.join(parts)}<p>Official listing text was rechecked via web on 22 Oct 2026: <a href="https://themes.shopify.com/themes/dwell/presets/dwell">Dwell</a> and <a href="https://themes.shopify.com/themes/craft/presets/craft">Craft</a>. The listing documents merchandising intent; it does not prove current demo behavior. Remote Shopify pages were not modified. Reference photography is not used inside Habitat scenes.</p><p>Observed states come from the saved dossiers. Design differences and user-problem statements are expert proposals. Mobile menu/cart entry were recorded in those dossiers; successful mutation, payment, complete keyboard behavior and arbitrary loading states were not established.</p></body></html>''')
    (P/'comparisons/references.json').write_text(json.dumps({'researchDate':'2026-10-22','references':refs,'listingVerification':'Official pages opened by web tool, 2026-10-22; no new interactive capture','evidenceLimit':'Saved screenshots/dossiers establish only their observed route/state/viewport. No purchases or remote mutations.'},ensure_ascii=False,indent=2)+'\n')
    wirecss='''*{box-sizing:border-box}body{font:17px/1.5 Arial;margin:0;padding:35px;background:#fff;color:#222}h1{font-size:34px}h2{font-size:25px}h3{font-size:20px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:30px}.lane{border:2px solid #555;padding:25px}.wire{padding:18px;border:1px solid #777;margin:18px 0}.split{display:grid;grid-template-columns:1fr 3fr;gap:12px}.twoup{display:grid;grid-template-columns:1fr 1fr;gap:12px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.box{background:#e8e8e8;border:1px solid #777;padding:18px;min-height:100px}.panorama{min-height:145px}.portrait{min-height:230px}.table{display:grid;grid-template-columns:1fr 1fr;font-size:16px}.table div{border-bottom:1px solid #777;padding:12px}p{margin:12px 0}a{color:#222}@media(max-width:750px){body{padding:20px}.columns{grid-template-columns:1fr}.three{grid-template-columns:1fr}}'''
    furniture='''<h2>Spatial purchase mission</h2><p>Will it fit the room and access path?</p><div class="wire"><h3>Home</h3><div class="split"><div class="box">Room index<br>Living<br>Dining<br>Work<br>Rest</div><div class="box panorama">Panoramic room context</div></div><p>Measurement guide before purchase</p></div><div class="wire"><h3>Collection</h3><p>Room breadcrumb → type rail</p><div class="twoup"><div class="box">Whole object<br>Width × depth × height<br>Named finish · price</div><div class="box">Whole object<br>Diameter × height<br>Named finish · price</div></div></div><div class="wire"><h3>Product</h3><div class="box panorama">Room photograph</div><div class="twoup"><div class="box">Object image + diagram</div><div class="box">Common dimensions<br>Finish-specific package facts<br>Availability → purchase</div></div><div class="table"><div>Assembled</div><div>Package</div><div>Material / assembly</div><div>Access / actual delivery conditions</div></div></div>'''
    apparel='''<h2>Apparel purchase mission</h2><p>What fits my body and everyday style?</p><div class="wire"><h3>Home</h3><div class="twoup"><div class="box portrait">Outfit / portrait campaign</div><div class="box">Editorial statement<br>New arrivals CTA</div></div><p>Silhouette discovery</p></div><div class="wire"><h3>Collection</h3><p>Apparel categories → size / color filters</p><div class="three"><div class="box portrait">Portrait garment<br>Sizes · price</div><div class="box portrait">Portrait garment<br>Sizes · price</div><div class="box portrait">Portrait garment<br>Sizes · price</div></div></div><div class="wire"><h3>Product</h3><div class="twoup"><div class="box portrait">Outfit gallery</div><div class="box">Size / color<br>Garment measurements<br>Fabric / fit<br>Availability → purchase</div></div><p>Independent outfit products and fabric care</p></div>'''
    (P/'comparisons/neutral-structure.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Original neutral task comparison</title><style>{wirecss}</style></head><body><a href="../index.html">Back to storybook</a><h1>Task and structure, without decorative identity.</h1><p>Original review diagrams. Photography, theme branding, accent color and typeface styling suppressed. These are analytical structures, not screenshots of production or Shopify pages. Shared purchase controls remain shared.</p><div class="columns"><section class="lane">{furniture}</section><section class="lane">{apparel}</section></div><p>Furniture keeps spatial/assembled/package/access evaluation; apparel keeps silhouette/garment/size evaluation. Compare the corresponding reference scenes, not just these abstractions. No usability outcome is claimed.</p></body></html>')

def boards_and_zip():
    font=ImageFont.truetype(str(P/'assets/fonts/source-sans-pro-600.ttf'),26)
    small=ImageFont.truetype(str(P/'assets/fonts/source-sans-pro-400.ttf'),21)
    for s in scenes:
      widths=[720,417,292];thumbs=[]
      for d,w in zip(devices,widths):
        im=Image.open(P/f'images/{s["id"]}-{d}.png').convert('RGB');im=im.resize((w,round(im.height*w/im.width)),Image.Resampling.LANCZOS);thumbs.append(im)
      out=Image.new('RGB',(sum(widths)+112,max(i.height for i in thumbs)+150),'#e9e2d5');draw=ImageDraw.Draw(out);draw.text((28,18),f'HABITAT  /  {s["id"][:2]}  {s["title"]}',font=font,fill='#302c25');x=28
      for (d,v),im in zip(devices.items(),thumbs):
        draw.text((x,63),f'{d.title()}  {v[0]} × {v[1]}',font=small,fill='#302c25');out.paste(im,(x,104));x+=im.width+28
      out.save(P/f'boards/{s["id"]}.png',optimize=True)
    with zipfile.ZipFile(P/'Habitat-45-mockups.zip','w',zipfile.ZIP_DEFLATED) as z:
      for s in scenes:
       for d in devices:z.write(P/f'images/{s["id"]}-{d}.png',f'{s["id"]}-{d}.png')
    print('Packaged 45 current PNGs and 15 separate boards')

gallery();comparisons()
if all((P/f'images/{s["id"]}-{d}.png').exists() for s in scenes for d in devices):boards_and_zip()
else:print('Gallery/source comparison HTML prepared; screenshots pending')
